from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
LeftDrive = Motor(Port.A, Direction.COUNTERCLOCKWISE)
RightDrive = Motor(Port.E, Direction.CLOCKWISE)
DriveBase1 = DriveBase(LeftDrive, RightDrive, 68.8, 6 * 25.4)
TopAttach = Motor(Port.B, Direction.CLOCKWISE)
SideAttach = Motor(Port.F, Direction.CLOCKWISE)
LeftColor = ColorSensor(Port.C)
RightColor = ColorSensor(Port.D)
LeftHitBlack = 0
RightHitBlack = 0


# The main program starts here.
print('Hello, Pybricks!')
DriveBase1.use_gyro(True)
DriveBase1.straight(250, then=Stop.NONE)
while not (LeftColor.reflection() >= 95 or RightColor.reflection() >= 95):
    wait(0)
print('Hit White')
DriveBase1.brake()
while LeftHitBlack == 0 or RightHitBlack == 0:
    if LeftColor.reflection() >= 20:
        LeftDrive.dc(30)
    else:
        LeftDrive.dc(0)
        LeftDrive.brake()
        LeftHitBlack = 1
        print('Left Hit Black!')
    if RightColor.reflection() >= 20:
        RightDrive.dc(30)
    else:
        RightDrive.dc(0)
        RightDrive.brake()
        RightHitBlack = 1
        print('Right Hit Black!')
while LeftHitBlack == 1 or RightHitBlack == 1:
    if LeftColor.reflection() <= 90:
        LeftDrive.dc(-20)
    else:
        LeftDrive.dc(0)
        LeftDrive.brake()
        LeftHitBlack = 0
        print('Left Hit White')
    if RightColor.reflection() <= 90:
        RightDrive.dc(-20)
    else:
        RightDrive.dc(0)
        RightDrive.brake()
        RightHitBlack = 0
        print('Right Hit White!')
